export function clientsFor(request: APIRequestContext, auth: AuthStrategy, service: ServicePack) {
  const redaction: RedactionPolicy = {
    identityFields: service.identity_fields,
    secretKeys: service.secret_keys,
  };
  return {
    realmsAdmin: new RealmsAdminClient(request, auth, redaction),
    attackDetection: new AttackDetectionClient(request, auth, redaction),
    authenticationManagement: new AuthenticationManagementClient(request, auth, redaction),
    clientRegistrationPolicy: new ClientRegistrationPolicyClient(request, auth, redaction),
    clientScopes: new ClientScopesClient(request, auth, redaction),
    protocolMappers: new ProtocolMappersClient(request, auth, redaction),
    scopeMappings: new ScopeMappingsClient(request, auth, redaction),
    clients: new ClientsClient(request, auth, redaction),
    clientInitialAccess: new ClientInitialAccessClient(request, auth, redaction),
    admin: new AdminClient(request, auth, redaction),
    clientAttributeCertificate: new ClientAttributeCertificateClient(request, auth, redaction),
    roles: new RolesClient(request, auth, redaction),
    component: new ComponentClient(request, auth, redaction),
    groups: new GroupsClient(request, auth, redaction),
    roleMapper: new RoleMapperClient(request, auth, redaction),
    clientRoleMappings: new ClientRoleMappingsClient(request, auth, redaction),
    identityProviders: new IdentityProvidersClient(request, auth, redaction),
    key: new KeyClient(request, auth, redaction),
    organizations: new OrganizationsClient(request, auth, redaction),
    rolesById: new RolesByIdClient(request, auth, redaction),
    users: new UsersClient(request, auth, redaction),
    workflows: new WorkflowsClient(request, auth, redaction),
  };
}

